import type { Exercise } from '../engine/types';

// Lot « testing » — exercices experts générés (multi-agent), ancrés sur des
// sources de référence. Options équilibrées, bonne réponse en index 0
// (position randomisée par shuffle.ts).
export const testingExercises: Exercise[] = [
  {"id":"tst-le-role-des-tests-lors-d-un-refactoring","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"Le rôle des tests lors d'un refactoring","company":"Kent Beck, «Test-Driven Development: By Example», sur la confiance et le refactoring","question":"Dans une optique de refactoring, quel rôle central jouent les tests automatisés ?","options":["Ils forment un filet de sécurité qui détecte les régressions quand on modifie le code","Ils remplacent entièrement la documentation fonctionnelle rédigée par les analystes métier du projet","Ils garantissent l'absence totale de bugs dans le logiciel une fois livré en production","Ils accélèrent l'exécution du code en production grâce à une meilleure compilation"],"answer":0,"explanation":"Les tests automatisés agissent comme un filet de sécurité : quand on restructure le code sans changer son comportement, une suite qui reste verte donne l'assurance de ne pas avoir introduit de régression. C'est précisément cette confiance qui rend le refactoring possible. Ils ne prouvent pas l'absence de bugs (ils ne testent que ce qu'on a prévu), ne remplacent pas la documentation et n'ont aucun effet sur les performances en production.","tags":["refactoring","filet-de-securite","regression","tdd"],"optionNotes":["Une suite verte après modification prouve l'absence de régression : c'est ce filet qui autorise le refactoring.","Les tests documentent le comportement mais ne remplacent pas la spécification fonctionnelle métier.","Ils ne testent que les cas prévus : verts, ils ne prouvent jamais l'absence totale de bugs.","Les tests s'exécutent hors production et n'ont aucun effet sur la vitesse du code livré."]},
  {"id":"tst-ce-qui-caracterise-un-test-unitaire","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"Ce qui caractérise un test unitaire","company":"Roy Osherove, «The Art of Unit Testing», ch. 1","question":"Qu'est-ce qui caractérise le mieux un test unitaire selon Osherove ?","options":["Il vérifie une petite unité de code de façon isolée, rapide et répétable","Il valide le parcours complet de l'utilisateur à travers l'interface graphique du produit","Il mesure les performances du système sous une charge de requêtes simultanées élevée","Il contrôle l'intégration entre plusieurs services et leur base de données réelle"],"answer":0,"explanation":"Osherove définit un test unitaire comme un test rapide, isolé, répétable et déterministe qui vérifie une petite unité de travail (souvent une méthode ou un comportement) sans dépendances externes réelles. Le parcours utilisateur complet relève du test e2e, la charge relève des tests de performance, et l'intégration entre services relève des tests d'intégration.","tags":["test-unitaire","definition","isolation","osherove"],"optionNotes":["Une petite unité vérifiée isolément, vite et de façon répétable : la définition d'Osherove.","Le parcours complet via l'interface relève du test end-to-end, pas du test unitaire.","Mesurer le comportement sous charge simultanée est un test de performance, pas unitaire.","Vérifier plusieurs services avec une vraie base est un test d'intégration."]},
  {"id":"tst-la-repartition-de-la-pyramide-des-tests","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"La répartition de la pyramide des tests","company":"Martin Fowler, «TestPyramid»; Mike Cohn, «Succeeding with Agile»","question":"Que recommande la pyramide des tests concernant la répartition des tests ?","options":["Beaucoup de tests unitaires à la base, moins d'intégration, peu de tests e2e au sommet","Autant de tests e2e que de tests unitaires afin de couvrir chaque couche de façon parfaitement égale","Une majorité de tests end-to-end car ils reproduisent le comportement réel de l'utilisateur","Uniquement des tests d'intégration, jugés plus fiables que les tests isolés"],"answer":0,"explanation":"La pyramide place à la base une grande quantité de tests unitaires (rapides, stables, peu coûteux), une couche intermédiaire de tests d'intégration, et une fine pointe de tests e2e (lents, fragiles, coûteux). Inverser ces proportions donne une suite lente et instable. La pyramide est une heuristique de répartition, pas une règle de couverture égale.","tags":["pyramide","repartition","unitaire","e2e"],"optionNotes":["Large base d'unitaires rapides, moins d'intégration, une pointe d'e2e : la forme pyramidale.","Égaliser unitaires et e2e ignore leurs coûts : la pyramide n'est pas une couverture égale.","Majorité d'e2e = pyramide inversée (cornet de glace) : suite lente et fragile.","Les unitaires isolés restent indispensables ; l'intégration seule laisse des trous."]},
  {"id":"tst-l-ordre-du-cycle-tdd","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"L'ordre du cycle TDD","company":"Kent Beck, «Test-Driven Development: By Example»","question":"Quel est l'ordre correct des étapes du cycle TDD ?","options":["Red (écrire un test qui échoue), Green (le faire passer), Refactor (améliorer)","Green (écrire le code qui marche), Red (écrire le test associé), Refactor (nettoyer le tout)","Refactor (préparer le terrain), Red (coder la fonctionnalité), Green (documenter le résultat)","Red (concevoir l'architecture), Green (déployer en recette), Refactor (relire en équipe)"],"answer":0,"explanation":"Le cycle TDD est Red-Green-Refactor : on écrit d'abord un test qui échoue (Red) car la fonctionnalité n'existe pas, on écrit le minimum de code pour le faire passer (Green), puis on améliore la structure du code en gardant les tests verts (Refactor). Écrire le code avant le test n'est plus du TDD.","tags":["tdd","red-green-refactor","cycle","kent-beck"],"optionNotes":["Red-Green-Refactor : test qui échoue, code minimal pour le vert, puis amélioration.","Écrire le code avant le test n'est plus du TDD : le test doit échouer d'abord.","Refactor vient en dernier, une fois le test vert, et ne sert pas à documenter.","Le test ne conçoit pas l'architecture ni ne déploie : il pilote le code par un échec initial."]},
  {"id":"tst-l-acronyme-first","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"L'acronyme FIRST","company":"Robert C. Martin, «Clean Code», ch. 9","question":"Que désignent les lettres de l'acronyme FIRST pour un bon test unitaire ?","options":["Fast, Isolated, Repeatable, Self-validating, Timely","Fast, Integrated, Reusable, Scalable, Testable","Formal, Independent, Robust, Simple, Traceable","Functional, Isolated, Reliable, Static, Typed"],"answer":0,"explanation":"FIRST résume les qualités d'un bon test unitaire : Fast (rapide), Isolated/Independent (isolé et indépendant des autres tests), Repeatable (reproductible dans tout environnement), Self-validating (auto-vérifiant, conclut seul succès/échec) et Timely (écrit au bon moment, idéalement juste avant le code en TDD).","tags":["first","qualite-test","fondamentaux","clean-code"],"optionNotes":["Fast, Isolated, Repeatable, Self-validating, Timely : les cinq qualités d'un bon test unitaire.","Integrated et Scalable contredisent l'esprit unitaire : un test doit être isolé, pas intégré.","Formal ou Traceable ne font pas partie de FIRST : c'est une définition inventée.","Static ou Typed concernent le code, pas les propriétés FIRST d'un test."]},
  {"id":"tst-le-pattern-arrange-act-assert","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"Le pattern Arrange-Act-Assert","company":"Roy Osherove, «The Art of Unit Testing», ch. 2","question":"Que structurent les trois phases du pattern Arrange-Act-Assert ?","options":["La préparation du contexte, l'exécution de l'action, puis la vérification du résultat obtenu","L'allocation de la mémoire, l'appel réseau distant, puis la libération des ressources utilisées","L'analyse du besoin métier, l'assignation des tâches, puis l'audit final du code produit","L'authentification du compte, l'autorisation des droits, puis l'accès aux données protégées"],"answer":0,"explanation":"AAA découpe un test en trois blocs lisibles : Arrange (préparer les données et l'objet testé), Act (exécuter l'action à vérifier, idéalement une seule), Assert (vérifier le résultat attendu). Cette structure rend l'intention du test explicite et facilite le diagnostic en cas d'échec.","tags":["aaa","arrange-act-assert","structure","lisibilite"],"optionNotes":["Arrange prépare le contexte, Act exécute l'action, Assert vérifie le résultat attendu.","Allouer/appeler/libérer décrit une gestion de ressources, pas la structure d'un test AAA.","Analyser/assigner/auditer relève de la gestion de projet, pas du pattern de test.","Authentifier/autoriser/accéder sont les trois A de la sécurité, pas d'AAA."]},
  {"id":"tst-test-d-integration-vs-test-unitaire","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"Test d'intégration vs test unitaire","company":"Vladimir Khorikov, «Unit Testing Principles, Practices, and Patterns», ch. 8","question":"Qu'est-ce qui distingue un test d'intégration d'un test unitaire ?","options":["Il vérifie que plusieurs composants réels fonctionnent correctement ensemble","Il s'exécute toujours plus vite car il n'utilise jamais aucune dépendance externe","Il teste une seule fonction en remplaçant toutes ses collaborations par des mocks","Il ne peut être écrit qu'après la mise en production complète de l'application"],"answer":0,"explanation":"Un test d'intégration vérifie la collaboration entre plusieurs composants et/ou avec des dépendances hors-processus réelles (base de données, système de fichiers, service). Il est généralement plus lent et plus fragile qu'un test unitaire, qui lui isole une unité de code. Il peut évidemment être écrit avant la mise en production.","tags":["integration","unitaire","dependances","khorikov"],"optionNotes":["Il vérifie que plusieurs composants réels collaborent correctement ensemble.","Faux : sollicitant des dépendances réelles, il est en général plus lent qu'un unitaire.","Isoler une fonction en mockant ses collaborations décrit justement le test unitaire.","Un test d'intégration s'écrit et s'exécute bien avant toute mise en production."]},
  {"id":"tst-ce-que-valide-un-test-end-to-end","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"Ce que valide un test end-to-end","company":"Martin Fowler, «TestPyramid»","question":"Que valide principalement un test end-to-end (e2e) ?","options":["Le parcours complet du système du point de vue de l'utilisateur final","Une méthode isolée dont toutes les dépendances externes sont remplacées","La couverture ligne par ligne d'un module de calcul purement interne","La conformité du style de code aux règles de linting définies pour le projet"],"answer":0,"explanation":"Un test e2e exerce l'application dans son ensemble, à travers ses interfaces réelles, pour valider un scénario utilisateur complet (par exemple : se connecter, ajouter un article au panier, payer). Il est précieux mais lent et fragile, d'où sa place réduite au sommet de la pyramide.","tags":["e2e","end-to-end","parcours-utilisateur","pyramide"],"optionNotes":["Il exerce le système entier via ses interfaces réelles pour valider un scénario utilisateur.","Isoler une méthode en remplaçant ses dépendances décrit le test unitaire, pas l'e2e.","La couverture ligne par ligne d'un module interne relève des tests unitaires.","Vérifier le style de code est du linting, pas un test end-to-end."]},
  {"id":"tst-a-quoi-sert-une-doublure-de-test","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"À quoi sert une doublure de test","company":"Gerard Meszaros, «xUnit Test Patterns», Test Double","question":"À quoi sert une doublure de test (test double) en général ?","options":["À remplacer une dépendance réelle pour tester le code de manière isolée et contrôlée","À dupliquer le test afin de l'exécuter deux fois de suite pour renforcer sa fiabilité","À doubler la vitesse d'exécution de la suite en parallélisant automatiquement les assertions","À copier le code de production pour comparer ligne à ligne les deux versions obtenues"],"answer":0,"explanation":"Une doublure de test (dummy, stub, mock, spy, fake) remplace une dépendance réelle par un substitut contrôlable. Cela permet d'isoler l'unité testée, de rendre le test rapide et déterministe, et de simuler des cas difficiles à provoquer (erreur réseau, réponse précise). Le mot « double » désigne le remplacement, pas une exécution en double.","tags":["test-double","doublure","isolation","meszaros"],"optionNotes":["Elle substitue une dépendance réelle pour tester l'unité de façon isolée et contrôlée.","« Double » désigne le remplacement de la dépendance, pas une double exécution du test.","Une doublure ne parallélise rien : elle isole, elle n'accélère pas les assertions.","Elle ne copie pas le code de production : elle en simule une dépendance."]},
  {"id":"tst-ce-que-mesure-la-couverture-de-code","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"Ce que mesure la couverture de code","company":"Vladimir Khorikov, «Unit Testing...», ch. 1","question":"Que mesure la couverture de code (code coverage) ?","options":["La proportion de code exécutée au moins une fois par la suite de tests","Le nombre de bugs encore présents et détectés directement en production","La qualité des assertions écrites à l'intérieur de chacun des tests","Le temps total d'exécution de l'ensemble de la suite de tests"],"answer":0,"explanation":"La couverture indique quelle part du code (lignes, branches, instructions) est traversée par l'exécution des tests. C'est une métrique utile pour repérer du code jamais testé, mais elle ne dit rien de la qualité des vérifications : du code exécuté sans assertion pertinente reste non testé de fait.","tags":["couverture","coverage","metrique","limites"],"optionNotes":["Elle mesure la part du code (lignes, branches) exécutée au moins une fois par les tests.","Elle compte le code parcouru, pas les bugs restants détectés en production.","Elle ignore la pertinence des assertions : du code exécuté sans vérification reste non testé.","Elle ne mesure pas le temps d'exécution de la suite, seulement le code traversé."]},
  {"id":"tst-un-test-deterministe","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"Un test déterministe","company":"Roy Osherove, «The Art of Unit Testing», ch. 7","question":"Que signifie qu'un test est déterministe ?","options":["Il produit toujours le même résultat pour les mêmes entrées et le même code","Il détermine automatiquement quelles fonctions du projet doivent être testées","Il s'arrête dès la toute première assertion qui échoue dans le fichier de test","Il dépend de l'heure système courante pour choisir son jeu de données d'entrée"],"answer":0,"explanation":"Un test déterministe donne systématiquement le même verdict tant que le code et les entrées ne changent pas. Les dépendances au temps, à l'aléa, à l'ordre d'exécution ou à un état partagé cassent le déterminisme et produisent des tests flaky. Le déterminisme est indispensable pour faire confiance à un échec.","tags":["deterministe","repetabilite","flaky","first"],"optionNotes":["Mêmes entrées et même code donnent toujours le même verdict : c'est le déterminisme.","Un test ne choisit pas quelles fonctions tester : c'est le rôle du développeur.","S'arrêter à la première assertion échouée décrit un comportement de runner, pas le déterminisme.","Dépendre de l'heure système casse justement le déterminisme et rend le test flaky."]},
  {"id":"tst-un-test-auto-verifiant","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"Un test auto-vérifiant","company":"Robert C. Martin, «Clean Code», ch. 9 (FIRST)","question":"Que veut dire qu'un test est « auto-vérifiant » (self-validating) ?","options":["Il conclut seul par un succès ou un échec, sans inspection manuelle du résultat","Il corrige automatiquement le code de production dès qu'une assertion échoue","Il génère lui-même les données d'entrée nécessaires à sa propre exécution","Il se réécrit à chaque exécution pour rester synchronisé avec le code testé"],"answer":0,"explanation":"Auto-vérifiant signifie que le test porte lui-même son verdict via des assertions : il passe ou il échoue, sans qu'un humain doive lire un journal ou comparer une sortie à l'œil. Un test qui se contente d'afficher des valeurs à inspecter n'est pas auto-vérifiant.","tags":["self-validating","assertion","first","verdict"],"optionNotes":["Ses assertions portent le verdict : il passe ou échoue seul, sans inspection manuelle.","Un test signale une erreur mais ne corrige jamais automatiquement le code de production.","Générer ses données n'est pas être auto-vérifiant : c'est l'assertion qui l'est.","Un test ne se réécrit pas seul : ce serait perdre toute valeur de vérification."]},
  {"id":"tst-l-anti-pattern-du-cornet-de-glace","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"L'anti-pattern du cornet de glace","company":"Martin Fowler, «TestPyramid» (inversion de la pyramide)","question":"Que décrit l'anti-pattern du « cornet de glace » (ice cream cone) ?","options":["Une majorité de tests e2e et manuels au sommet, et très peu de tests unitaires à la base","Une suite composée uniquement de tests unitaires ultra-rapides et sans intégration","Des tests dupliqués qui vérifient tous exactement le même comportement métier","Une couverture de code volontairement maintenue à cent pour cent en permanence"],"answer":0,"explanation":"Le cornet de glace est la pyramide renversée : une énorme couche de tests e2e (et souvent de tests manuels) au sommet, une base minuscule de tests unitaires. Résultat : une suite lente, fragile et coûteuse à maintenir, avec un feedback tardif. C'est le symptôme typique d'une équipe qui a testé « par le haut » sans investir dans les tests unitaires.","tags":["ice-cream-cone","anti-pattern","pyramide","e2e"],"optionNotes":["Pyramide inversée : masse d'e2e et de tests manuels au sommet, base d'unitaires minuscule.","Une suite purement unitaire n'est pas le cornet de glace : celui-ci sur-investit l'e2e.","Des tests dupliqués sont un autre smell, pas l'inversion de la pyramide.","Viser 100 % de couverture n'est pas le cornet de glace, qui concerne la répartition."]},
  {"id":"tst-la-formulation-given-when-then","type":"mcq","domain":"software","topic":"testing","difficulty":"junior","title":"La formulation Given-When-Then","company":"Dan North, BDD; Freeman & Pryce, «Growing Object-Oriented Software»","question":"À quoi correspond la formulation « Given-When-Then » d'un test ?","options":["Une reformulation d'Arrange-Act-Assert issue du BDD, centrée sur le comportement","Une technique de génération aléatoire des données d'entrée d'un test unitaire","Une méthode de mesure de la couverture des branches conditionnelles du code","Un algorithme de détection automatique des tests flaky dans la chaîne d'intégration"],"answer":0,"explanation":"Given-When-Then est le vocabulaire du BDD (Behavior-Driven Development) : Given (contexte initial), When (événement/action), Then (résultat attendu). Il correspond conceptuellement à Arrange-Act-Assert, mais met l'accent sur la description du comportement métier en langage lisible par les parties prenantes.","tags":["given-when-then","bdd","aaa","comportement"],"optionNotes":["Vocabulaire BDD équivalent à AAA : Given contexte, When action, Then résultat attendu.","La génération aléatoire d'entrées est du property-based testing, pas Given-When-Then.","Mesurer la couverture des branches n'a aucun rapport avec cette formulation BDD.","Détecter les tests flaky est un tout autre sujet que la description du comportement."]},
  {"id":"tst-le-test-qui-ne-teste-rien","type":"find-error","domain":"software","topic":"testing","difficulty":"junior","title":"Le test qui ne teste rien","company":"Robert C. Martin, «Clean Code», ch. 9 (Self-validating); Osherove","language":"python","code":"def test_utilisateur_est_majeur():\n    utilisateur = Utilisateur(age=20)\n    utilisateur.est_majeur()  # renvoie True ou False","question":"Quel défaut rend ce test totalement inutile ?","options":["Le résultat de est_majeur() n'est jamais passé à une assertion : le test réussit toujours","L'objet Utilisateur devrait être créé après l'appel à la méthode est_majeur()","Le test devrait plutôt utiliser un âge négatif afin de couvrir davantage de branches","La méthode est_majeur() doit être renommée pour respecter correctement le pattern AAA"],"answer":0,"explanation":"Le test appelle est_majeur() mais ne vérifie jamais sa valeur de retour : il n'y a aucune assertion. Comme aucune exception n'est levée, il passe systématiquement, même si est_majeur() est buggée. Un test doit être auto-vérifiant, par exemple : assert utilisateur.est_majeur() is True. C'est un cas classique de test « toujours vert » qui donne une fausse assurance.","tags":["assertion-manquante","self-validating","faux-positif","python"],"optionNotes":["est_majeur() est appelée mais sa valeur n'est jamais assertée : sans exception, le test passe toujours.","L'ordre de création n'est pas le défaut : c'est l'absence d'assertion qui rend le test inutile.","Ajouter des branches ne corrige rien tant qu'aucune assertion ne vérifie le résultat.","Renommer la méthode ne change rien : il manque une assertion, pas un respect d'AAA."]},
  {"id":"tst-un-test-flaky","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"Un test flaky","company":"Martin Fowler, «Eradicating Non-Determinism in Tests»","question":"Qu'est-ce qu'un test « flaky » (instable) ?","options":["Un test qui passe ou échoue de façon intermittente sans aucune modification du code","Un test volontairement désactivé par l'équipe car il n'est plus jugé pertinent","Un test qui vérifie plusieurs choses distinctes dans une même et unique assertion","Un test dont le pourcentage de couverture reste inférieur à un seuil défini"],"answer":0,"explanation":"Un test flaky donne un verdict non déterministe : rejoué sur le même code, il passe parfois et échoue d'autres fois. Ses causes fréquentes sont la dépendance au temps, à l'aléa, à l'ordre d'exécution, à la concurrence ou à un état partagé mal réinitialisé. Les tests flaky détruisent la confiance dans la suite car on finit par ignorer leurs échecs.","tags":["flaky","instable","non-deterministe","fiabilite"],"optionNotes":["Il passe ou échoue par intermittence sur le même code : un verdict non déterministe.","Un test désactivé est ignoré, pas flaky : le flaky s'exécute et change d'avis.","Vérifier plusieurs choses dans une assertion est un autre smell, pas la flakiness.","Une couverture sous un seuil n'a rien à voir avec l'instabilité d'un test."]},
  {"id":"tst-distinguer-un-stub-d-un-mock","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"Distinguer un stub d'un mock","company":"Martin Fowler, «Mocks Aren't Stubs»; Gerard Meszaros","question":"Selon la distinction de Fowler, qu'est-ce qui différencie un stub d'un mock ?","options":["Le stub fournit des réponses prédéfinies ; le mock vérifie en plus les interactions attendues","Le mock fournit des données figées ; le stub échoue si une méthode n'est jamais appelée","Le stub simule uniquement le réseau tandis que le mock simule uniquement la base de données","Le mock est toujours écrit à la main alors que le stub provient forcément d'un framework"],"answer":0,"explanation":"Un stub alimente le code testé avec des réponses préparées (état) : il permet d'exécuter un chemin donné. Un mock, lui, sert à vérifier le comportement : on lui fixe des attentes sur les appels reçus, et le test échoue si ces interactions ne se produisent pas. Le stub relève de la vérification d'état, le mock de la vérification d'interaction.","tags":["stub","mock","fowler","test-double"],"optionNotes":["Le stub renvoie des réponses préparées (état) ; le mock vérifie en plus les interactions.","Inversé : c'est le stub qui fige des données et le mock qui contrôle les appels reçus.","Ni stub ni mock ne se limitent au réseau ou à la base : la distinction est état vs interaction.","L'origine (main ou framework) ne distingue pas stub et mock : c'est leur rôle qui compte."]},
  {"id":"tst-tester-le-comportement-plutot-que-l-impl","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"Tester le comportement plutôt que l'implémentation","company":"Vladimir Khorikov, «Unit Testing...», ch. 5","question":"Pourquoi privilégier le test du comportement plutôt que de l'implémentation interne ?","options":["Les tests restent valides après un refactoring qui ne change pas le comportement observable","Les tests s'exécutent plus vite car ils inspectent directement les variables privées de l'objet","Les tests atteignent ainsi plus facilement cent pour cent de couverture des lignes internes","Les tests peuvent alors se passer totalement d'assertions sur le résultat produit"],"answer":0,"explanation":"Tester le comportement observable via l'API publique découple les tests des détails internes. On peut alors restructurer l'implémentation (renommer, extraire, réorganiser) sans casser les tests, ce qui est exactement le but recherché pour refactorer en confiance. À l'inverse, tester l'implémentation (états privés, appels internes) rend les tests fragiles et bloque le refactoring.","tags":["comportement","implementation","resistance-refactoring","khorikov"],"optionNotes":["Testé par l'API publique, le test survit à tout refactoring qui garde le comportement intact.","Inspecter des variables privées couple le test à l'interne et ne l'accélère pas.","Viser 100 % de couverture interne n'est pas le but : la résistance au refactoring l'est.","Tester le comportement exige toujours des assertions sur le résultat produit."]},
  {"id":"tst-les-limites-de-la-couverture-de-code","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"Les limites de la couverture de code","company":"Vladimir Khorikov, «Unit Testing...», ch. 1","question":"Pourquoi une couverture de 100 % ne garantit-elle pas l'absence de bugs ?","options":["Exécuter une ligne ne prouve pas que son résultat soit réellement vérifié par une assertion","Les outils de couverture ignorent systématiquement toutes les branches conditionnelles du code","La couverture ne peut de toute façon jamais dépasser 80 % sur un vrai projet en production","Le code couvert par les tests est automatiquement exclu de la compilation finale du binaire"],"answer":0,"explanation":"La couverture ne mesure que l'exécution du code, pas la pertinence des vérifications. On peut traverser 100 % des lignes sans jamais asserter les bons résultats, ou sans couvrir les cas limites et les combinaisons d'entrées qui font échouer le programme. La couverture repère le code non testé, mais un chiffre élevé n'est pas une preuve de qualité.","tags":["couverture","illusion","assertion","limites"],"optionNotes":["Exécuter une ligne ne prouve pas que son résultat soit vérifié par une assertion.","Faux : les outils de couverture savent instrumenter les branches conditionnelles.","La couverture peut atteindre 100 % : aucune limite intrinsèque à 80 %.","Le code couvert reste compilé normalement : la couverture n'exclut rien du binaire."]},
  {"id":"tst-differencier-un-dummy-d-un-fake","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"Différencier un dummy d'un fake","company":"Gerard Meszaros, «xUnit Test Patterns»","question":"Qu'est-ce qui distingue un « dummy » d'un « fake » ?","options":["Le dummy n'est jamais vraiment utilisé ; le fake a une implémentation allégée mais fonctionnelle","Le dummy renvoie des valeurs configurées à l'avance ; le fake se contente de vérifier les appels","Le dummy simule une base de données réelle ; le fake remplace uniquement le service réseau","Le dummy est généré par un framework de test ; le fake est toujours écrit entièrement à la main"],"answer":0,"explanation":"Un dummy est un objet passé uniquement pour satisfaire une signature : il n'est jamais réellement sollicité (souvent un null ou un objet vide). Un fake possède une vraie implémentation simplifiée mais opérationnelle (par exemple un dépôt en mémoire remplaçant une base de données). Le stub renvoie des valeurs préparées, le mock vérifie les interactions.","tags":["dummy","fake","test-double","meszaros"],"optionNotes":["Le dummy n'est jamais réellement utilisé ; le fake a une implémentation allégée mais fonctionnelle.","Renvoyer des valeurs (stub) ou vérifier des appels (mock) ne décrit ni le dummy ni le fake.","Le fake n'est pas cantonné au réseau ni le dummy à la base : la distinction est ailleurs.","L'origine (framework ou main) ne définit pas dummy et fake : c'est leur usage."]},
  {"id":"tst-le-role-d-un-spy","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"Le rôle d'un spy","company":"Gerard Meszaros; Roy Osherove, «The Art of Unit Testing»","question":"Quel est le rôle principal d'un « spy » ?","options":["Enregistrer les appels reçus afin de les vérifier après coup dans la phase Assert","Fournir des réponses entièrement prédéfinies sans jamais enregistrer la moindre information","Remplacer complètement la base de données réelle par une version fonctionnelle en mémoire","Occuper une place dans une signature de méthode sans jamais être appelé par le code"],"answer":0,"explanation":"Un spy est une doublure qui enregistre les informations sur la façon dont elle a été utilisée (arguments reçus, nombre d'appels), pour que le test les vérifie ensuite. Il se rapproche du mock, mais la vérification se fait a posteriori dans l'Assert plutôt que par des attentes fixées à l'avance.","tags":["spy","test-double","interaction","assert"],"optionNotes":["Le spy enregistre les appels reçus pour que le test les vérifie ensuite dans l'Assert.","Fournir des réponses figées sans rien enregistrer décrit le stub, pas le spy.","Remplacer la base par une version en mémoire décrit le fake, pas le spy.","Occuper une signature sans être appelé décrit le dummy, pas le spy."]},
  {"id":"tst-l-etape-refactor-du-cycle-tdd","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"L'étape Refactor du cycle TDD","company":"Kent Beck, «Test-Driven Development: By Example»","question":"Que fait-on précisément durant l'étape « Refactor » du cycle TDD ?","options":["On améliore la structure du code tout en gardant les tests au vert, sans changer le comportement","On ajoute de nouvelles fonctionnalités en écrivant d'abord le code puis les tests correspondants","On supprime au passage les tests devenus redondants afin d'accélérer l'exécution de la suite","On réécrit les tests existants pour qu'ils correspondent au code qui vient d'être produit"],"answer":0,"explanation":"Une fois le test au vert, l'étape Refactor consiste à éliminer la duplication et à améliorer la conception (nommage, extraction, structure) en s'appuyant sur les tests comme filet de sécurité. Le comportement observable ne change pas, donc les tests restent verts. On n'ajoute aucune fonctionnalité ni ne réécrit les tests pour coller au code durant cette phase.","tags":["refactor","tdd","conception","filet-de-securite"],"optionNotes":["On améliore la structure du code, tests verts, sans modifier le comportement observable.","Ajouter une fonctionnalité relance un cycle Red : Refactor ne crée aucun comportement.","Supprimer des tests n'est pas l'objet de Refactor, qui s'appuie sur eux comme filet.","Réécrire les tests pour coller au code trahit l'esprit du TDD : le test guide le code."]},
  {"id":"tst-pourquoi-peu-de-tests-e2e","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"Pourquoi peu de tests e2e","company":"Martin Fowler, «TestPyramid»","question":"Pourquoi la pyramide place-t-elle peu de tests e2e au sommet ?","options":["Les tests e2e sont lents, coûteux à maintenir et statistiquement plus fragiles que les autres","Les tests e2e sont totalement inutiles dès lors qu'il existe des tests unitaires dans le projet","Les tests e2e ne peuvent tout simplement pas être automatisés dans une chaîne d'intégration","Les tests e2e couvrent structurellement moins de code que les tests unitaires isolés"],"answer":0,"explanation":"Les tests e2e traversent tout le système via ses interfaces réelles : ils sont lents, sensibles aux aléas (réseau, timing, données) donc plus flaky, et coûteux à maintenir quand l'interface évolue. On en garde donc un petit nombre ciblé sur les parcours critiques, en s'appuyant sur les couches inférieures pour le gros de la vérification. Ils restent utiles, complémentaires et automatisables.","tags":["e2e","pyramide","cout","fragilite"],"optionNotes":["Lents, coûteux à maintenir et plus fragiles, les e2e se limitent aux parcours critiques.","Faux : les e2e restent utiles et complémentaires même avec de bons tests unitaires.","Les e2e s'automatisent parfaitement dans une CI : ce n'est pas la raison de leur rareté.","Ils traversent tout le système et couvrent souvent plus de code, pas moins."]},
  {"id":"tst-le-principe-du-property-based-testing","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"Le principe du property-based testing","company":"Claessen & Hughes, QuickCheck","question":"Sur quel principe repose le property-based testing ?","options":["Vérifier qu'une propriété reste vraie pour de nombreuses entrées générées automatiquement","Écrire un test manuel distinct et exhaustif pour chaque valeur d'entrée possible du domaine","Mesurer les propriétés de performance du code lorsqu'il est soumis à une charge importante","Générer automatiquement les mocks nécessaires à partir des interfaces déclarées du projet"],"answer":0,"explanation":"Le property-based testing exprime une propriété générale attendue (par exemple : décoder(encoder(x)) == x, ou trier une liste préserve sa longueur), puis un framework génère de nombreuses entrées aléatoires pour tenter de la mettre en défaut. Cela explore un espace bien plus large qu'un jeu d'exemples choisis à la main et révèle des cas limites inattendus.","tags":["property-based","quickcheck","proprietes","generation"],"optionNotes":["On énonce une propriété générale et un framework génère de nombreuses entrées pour la réfuter.","Écrire un test par valeur possible est l'approche par exemples, l'inverse du property-based.","Mesurer les performances sous charge est un test de charge, pas du property-based.","Le property-based génère des entrées, pas des mocks à partir d'interfaces."]},
  {"id":"tst-ce-que-mesure-le-mutation-testing","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"Ce que mesure le mutation testing","company":"Littérature mutation testing (PIT, Stryker)","question":"Que mesure le mutation testing ?","options":["La capacité des tests à détecter des modifications introduites dans le code (mutants tués)","Le pourcentage de lignes du code source exécutées au moins une fois par la suite de tests","Le temps moyen nécessaire pour transformer une branche conditionnelle en boucle équivalente","Le nombre de doublures nécessaires pour isoler complètement une classe de ses collaborateurs"],"answer":0,"explanation":"Le mutation testing introduit de petites modifications (mutants) dans le code — inverser une condition, changer un opérateur — puis relance les tests. Si un test échoue, le mutant est « tué » (bon signe). S'il survit, c'est qu'aucun test ne détecte ce changement de comportement : une lacune de la suite. C'est une mesure de qualité des tests bien plus exigeante que la simple couverture de lignes.","tags":["mutation-testing","mutants","qualite-tests","couverture"],"optionNotes":["Il mesure si les tests détectent des mutations introduites dans le code : les mutants tués.","Le pourcentage de lignes exécutées est la couverture, une métrique bien plus faible.","Transformer une branche en boucle n'a aucun sens ici : les mutants sont de petits changements.","Le nombre de doublures ne mesure rien : le mutation testing évalue la qualité des tests."]},
  {"id":"tst-tester-du-code-pur-vs-impur","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"Tester du code pur vs impur","company":"Vladimir Khorikov, «Unit Testing...», ch. 6 (functional architecture)","question":"Pourquoi le code pur (sans effet de bord) est-il plus facile à tester ?","options":["Sa sortie ne dépend que de ses entrées, sans I/O, temps ni aléa à simuler dans le test","Il s'exécute nécessairement en parallèle sur plusieurs cœurs, ce qui accélère la vérification","Il n'a pas besoin d'assertions puisque son résultat calculé est par nature toujours correct","Il est automatiquement couvert à cent pour cent par les outils de mesure de couverture"],"answer":0,"explanation":"Une fonction pure retourne toujours le même résultat pour les mêmes entrées et ne produit aucun effet de bord. On la teste sans mocks, sans base de données, sans horloge ni générateur aléatoire : on fournit des entrées, on vérifie la sortie. Une stratégie courante (functional core, imperative shell) consiste à concentrer la logique dans du code pur et à repousser les I/O aux frontières.","tags":["code-pur","effets-de-bord","functional-core","testabilite"],"optionNotes":["Sa sortie ne dépend que des entrées : ni I/O, ni temps, ni aléa à simuler dans le test.","Le code pur ne s'exécute pas forcément en parallèle : sa testabilité vient du déterminisme.","Même pur, un résultat doit être asserté : le calcul n'est pas correct par nature.","La pureté facilite le test mais ne garantit aucune couverture automatique de 100 %."]},
  {"id":"tst-le-role-du-contract-testing","type":"mcq","domain":"software","topic":"testing","difficulty":"intermediate","title":"Le rôle du contract testing","company":"Pact; Martin Fowler, «ContractTest»","question":"Que vérifie le contract testing entre deux services ?","options":["Que le producteur et le consommateur respectent un même contrat d'interface partagé","Que le service répond bien en moins d'un temps limite donné sous une forte charge","Que chaque ligne de code du service producteur est couverte par au moins un test","Que les mutants introduits dans le service consommateur sont tous correctement tués"],"answer":0,"explanation":"Le contract testing valide que les messages échangés entre un producteur (l'API) et un consommateur respectent un contrat commun (formats, champs, statuts). Chaque côté teste sa conformité au contrat de façon indépendante, ce qui détecte les ruptures de compatibilité sans avoir à déployer les deux services ensemble dans un lourd test e2e.","tags":["contract-testing","pact","interface","integration"],"optionNotes":["Il vérifie que producteur et consommateur respectent un même contrat d'interface partagé.","Répondre sous un délai limité est un test de performance, pas de contrat.","Couvrir chaque ligne du producteur est de la couverture, sans lien avec le contrat.","Tuer des mutants relève du mutation testing, pas du contract testing."]},
  {"id":"tst-le-test-asynchrone-toujours-vert","type":"find-error","domain":"software","topic":"testing","difficulty":"intermediate","title":"Le test asynchrone toujours vert","company":"Documentation Jest, «Testing Asynchronous Code»","language":"javascript","code":"test('recupere le nom de l utilisateur', () => {\n  fetchUser(1).then((user) => {\n    expect(user.name).toBe('Alice');\n  });\n});","question":"Pourquoi ce test peut-il rester vert même si user.name vaut « Bob » ?","options":["La promesse n'est ni attendue ni retournée : l'assertion s'exécute après la fin du test","expect().toBe() ne fonctionne pas avec des chaînes de caractères dans le moteur JavaScript","fetchUser doit être appelé avec await mais sans return, ce qui inverse le verdict du test","Le test manque un bloc Arrange explicite, ce qui empêche Jest de l'exécuter correctement"],"answer":0,"explanation":"Le callback du .then() s'exécute de façon asynchrone, après que la fonction de test synchrone s'est déjà terminée avec succès. L'échec de l'assertion survient trop tard pour être rattaché au test, qui reste vert. Il faut soit retourner la promesse (return fetchUser(1).then(...)), soit utiliser async/await : const user = await fetchUser(1); expect(user.name).toBe('Alice').","tags":["async","faux-positif","promise","jest"],"optionNotes":["La promesse n'est ni retournée ni attendue : l'assertion s'exécute après la fin du test synchrone.","Faux : toBe compare parfaitement les chaînes ; le vrai souci est l'asynchronisme non géré.","Ajouter await sans return corrigerait justement le bug : ce n'est pas ce qui inverse le verdict.","Le problème n'est pas un Arrange manquant mais une promesse non attendue par le test."]},
  {"id":"tst-un-mock-qui-sur-specifie-l-implementatio","type":"find-error","domain":"software","topic":"testing","difficulty":"intermediate","title":"Un mock qui sur-spécifie l'implémentation","company":"Vladimir Khorikov, «Unit Testing...», ch. 5 (overspecification)","language":"java","code":"@Test\nvoid enregistreUnNouvelUtilisateur() {\n    UserService service = new UserService(repo);\n    service.inscrire(\"alice@exemple.fr\");\n    verify(repo).existsByEmail(\"alice@exemple.fr\");\n    verify(repo).save(any(User.class));\n}","question":"Quel « test smell » ce test illustre-t-il principalement ?","options":["Il sur-spécifie l'implémentation en vérifiant existsByEmail, un détail interne non observable","Il oublie complètement d'instancier UserService avant d'appeler la méthode inscrire()","Il devrait mocker la classe User elle-même plutôt que le dépôt repo passé au service","Il mélange deux langages d'assertion incompatibles à l'intérieur d'un même test unitaire"],"answer":0,"explanation":"Vérifier repo.existsByEmail(...) verrouille un détail d'implémentation : la façon dont le service décide qu'un email est nouveau. Si demain on remplace ce contrôle par une contrainte d'unicité ou une autre stratégie, le comportement observable (l'utilisateur est bien enregistré) reste identique mais le test casse. C'est de la sur-spécification. Seul verify(repo).save(...), qui correspond à l'effet de bord attendu et observable, est justifié.","tags":["overspecification","mock","test-smell","fragilite"],"optionNotes":["Vérifier existsByEmail verrouille un détail interne : le test casse à un refactoring sans régression.","UserService est bien instancié : le défaut est la sur-spécification, pas une omission.","Mocker User n'aiderait pas : le smell est de vérifier un appel interne non observable.","Il n'y a pas deux langages d'assertion mêlés : le problème est l'over-specification."]},
  {"id":"tst-comparer-des-flottants-avec-egalite-stri","type":"find-error","domain":"software","topic":"testing","difficulty":"intermediate","title":"Comparer des flottants avec égalité stricte","company":"Documentation pytest, «pytest.approx»; norme IEEE 754","language":"python","code":"def test_somme_des_montants():\n    total = 0.1 + 0.2\n    assert total == 0.3","question":"Pourquoi ce test échoue-t-il alors que le calcul « paraît » correct ?","options":["0.1 + 0.2 vaut 0.30000000000000004 en flottant : il faut comparer avec une tolérance","L'opérateur == n'est tout simplement pas défini pour les nombres flottants en Python","Il manque un cast explicite en type float sur chacun des trois littéraux numériques","La somme déclenche silencieusement une exception d'overflow arithmétique à l'exécution"],"answer":0,"explanation":"Les nombres à virgule flottante (IEEE 754) ne représentent pas exactement 0.1, 0.2 ni 0.3. La somme donne 0.30000000000000004, différente de 0.3, donc l'égalité stricte échoue. Il faut comparer avec une tolérance : assert total == pytest.approx(0.3), ou assert abs(total - 0.3) < 1e-9. C'est une cause classique de test « mystérieusement rouge ».","tags":["flottants","ieee-754","tolerance","pytest"],"optionNotes":["0.1 + 0.2 vaut 0.30000000000000004 en IEEE 754 : il faut comparer avec une tolérance.","Faux : == est bien défini sur les flottants ; c'est l'arrondi binaire qui piège.","Un cast en float ne changerait rien : les littéraux sont déjà des flottants imprécis.","Aucun overflow ici : la somme est juste inexacte en représentation binaire."]},
  {"id":"tst-le-risque-des-mocks-sur-les-interactions","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"Le risque des mocks sur les interactions internes","company":"Vladimir Khorikov, «Unit Testing...», ch. 5 «Mocks and test fragility»","question":"Quel est le principal risque d'utiliser des mocks pour vérifier des interactions internes ?","options":["Coupler les tests à l'implémentation, ce qui les rend fragiles au moindre refactoring interne","Ralentir fortement l'exécution de la suite car les mocks accèdent réellement au disque","Empêcher structurellement d'atteindre un niveau de couverture de code élevé sur le module","Rendre impossible l'écriture ultérieure de tests d'intégration sur les mêmes composants"],"answer":0,"explanation":"Mocker des collaborateurs internes revient à figer la manière dont l'objet fait son travail, pas seulement ce qu'il produit. Un refactoring qui change ces interactions sans changer le comportement observable casse alors les tests : ils deviennent fragiles et découragent le refactoring. Khorikov recommande de ne mocker que les dépendances aux frontières hors-processus qui communiquent avec le monde extérieur, et de tester le reste par l'état.","tags":["mock","couplage","fragilite","refactoring"],"optionNotes":["Mocker l'interne couple le test à l'implémentation : il devient fragile au moindre refactoring.","Faux : un mock n'accède pas au disque, il est même plus rapide qu'une dépendance réelle.","Les mocks n'empêchent pas d'atteindre une couverture élevée : le risque est la fragilité.","Rien n'interdit d'écrire ensuite des tests d'intégration sur les mêmes composants."]},
  {"id":"tst-couverture-elevee-sans-assertion","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"Couverture élevée sans assertion","company":"Vladimir Khorikov, «Unit Testing...», ch. 1","question":"Un test exécute tout le code d'une fonction mais ne contient aucune assertion pertinente. Que peut-on en déduire sur la couverture ?","options":["La couverture peut être élevée tout en ne validant rien : c'est une fausse assurance","La couverture affichée sera automatiquement nulle du fait de l'absence d'assertion","Le test échouera systématiquement à l'exécution à cause de l'assertion manquante","La couverture des branches viendra compenser d'elle-même l'absence de vérification"],"answer":0,"explanation":"L'instrumentation de couverture compte les lignes exécutées, indépendamment des assertions. Un test sans vérification utile fait grimper la couverture tout en ne pouvant jamais échouer sur une régression : la métrique est verte, la protection réelle est nulle. C'est pourquoi la couverture doit se lire comme un détecteur de code non testé, jamais comme une preuve de qualité — et pourquoi le mutation testing la complète utilement.","tags":["couverture","assertion","illusion","mutation-testing"],"optionNotes":["Une couverture élevée sans assertion pertinente ne valide rien : c'est une fausse assurance.","Faux : la couverture compte les lignes exécutées, indépendamment de toute assertion.","Sans assertion, le test ne peut pas échouer : il reste vert, pas systématiquement rouge.","La couverture de branches ne compense pas l'absence de vérification du résultat."]},
  {"id":"tst-un-test-rouge-seulement-en-ci-parallele","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"Un test rouge seulement en CI parallèle","company":"Martin Fowler, «Eradicating Non-Determinism in Tests»","scenario":"Un test passe systématiquement en local mais échoue aléatoirement dans la CI qui exécute la suite en parallèle.","question":"Quelle cause est la plus probable de ce comportement ?","options":["Un état global partagé entre tests, sensible à l'ordre d'exécution et à la concurrence","Un nombre insuffisant d'assertions présentes dans le corps du test qui échoue","Une couverture de code trop élevée qui ralentit et surcharge l'environnement de CI","L'usage du pattern AAA au lieu de la formulation Given-When-Then dans le test"],"answer":0,"explanation":"Passer en local mais échouer en parallèle est la signature d'un état partagé mutable (variable globale, singleton, fichier, table de base non isolée, ordre implicite). En parallèle, deux tests se marchent dessus ; en local séquentiel, le problème reste masqué. Le remède : isoler l'état (fixtures fraîches, réinitialisation, données propres à chaque test) pour restaurer le déterminisme.","tags":["flaky","concurrence","etat-partage","isolation"],"optionNotes":["Passer en local mais échouer en parallèle signe un état global partagé, sensible à l'ordre.","Le nombre d'assertions n'explique pas une flakiness liée à la concurrence.","Une couverture élevée ne rend pas un test intermittent : la cause est l'état partagé.","Choisir AAA plutôt que Given-When-Then n'a aucun effet sur le déterminisme."]},
  {"id":"tst-interpreter-un-mutant-survivant","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"Interpréter un mutant survivant","company":"Littérature mutation testing (PIT, Stryker)","question":"Un mutant survit à votre suite de tests. Qu'est-ce que cela révèle avant tout ?","options":["Une lacune de la suite : aucun test n'échoue face à cette modification du comportement","Un bug certain et déjà présent dans le code de production qu'il faut corriger d'urgence","Une couverture de lignes nécessairement inférieure à cinquante pour cent sur le module","Un test flaky qu'il convient de supprimer immédiatement de la suite pour la stabiliser"],"answer":0,"explanation":"Un mutant survivant signifie qu'on a modifié le comportement du code sans qu'aucun test ne s'en aperçoive : il manque une assertion ou un cas de test. Ce n'est pas un bug du code de production (le mutant est artificiel) ni forcément lié à une faible couverture de lignes — une ligne peut être exécutée sans être vérifiée. La bonne réaction est d'ajouter le test qui tuerait ce mutant.","tags":["mutation-testing","mutant-survivant","lacune","assertion"],"optionNotes":["Un mutant survivant révèle une lacune : aucun test n'attrape cette modification du comportement.","Le mutant est artificiel : sa survie n'indique pas un bug réel en production.","Une ligne peut être exécutée sans être vérifiée : la survie n'implique pas < 50 % de couverture.","Ce n'est pas un test flaky à supprimer : il faut au contraire ajouter le test qui tue le mutant."]},
  {"id":"tst-ecole-classique-vs-ecole-mockiste","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"École classique vs école mockiste","company":"Vladimir Khorikov, «Unit Testing...», ch. 2; Freeman & Pryce, «GOOS»","question":"Qu'oppose la distinction entre l'école « classique » (Detroit) et l'école « mockiste » (London) du TDD ?","options":["L'usage des doublures : les mockistes isolent par des mocks, les classiques préfèrent des objets réels","Le langage de programmation employé, l'un orienté objet et l'autre purement fonctionnel","L'ordre du cycle : les mockistes débutent par le refactoring plutôt que par l'écriture du test","La cible testée : les classiques testent l'interface graphique, les mockistes la base de données"],"answer":0,"explanation":"L'école London (mockiste) isole l'unité sous test en remplaçant ses collaborateurs par des mocks, ce qui met l'accent sur les interactions et guide fortement le design. L'école Detroit (classique/classicist) utilise autant que possible des objets réels et vérifie l'état résultant, ne mockant que les dépendances gênantes. Khorikov plaide plutôt pour l'approche classique afin de limiter la fragilité des tests.","tags":["london","detroit","mockiste","classicist"],"optionNotes":["Les mockistes (London) isolent par des mocks ; les classiques (Detroit) préfèrent des objets réels.","Le clivage n'est pas le langage : les deux écoles s'appliquent aux mêmes paradigmes.","L'ordre du cycle Red-Green-Refactor est commun : il ne distingue pas les deux écoles.","Ni GUI ni base : la différence porte sur l'usage des doublures, pas sur la cible testée."]},
  {"id":"tst-les-quatre-piliers-d-un-bon-test-unitair","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"Les quatre piliers d'un bon test unitaire","company":"Vladimir Khorikov, «Unit Testing...», ch. 4","question":"Quels sont les quatre piliers d'un bon test unitaire selon Khorikov ?","options":["Protection contre les régressions, résistance au refactoring, feedback rapide, maintenabilité","Rapidité maximale, isolation totale, couverture la plus haute possible et nombre minimal de lignes","Lisibilité, documentation intégrée, exécution parallèle et indépendance vis-à-vis du framework","Automatisation, reproductibilité, portabilité entre environnements et sécurité des données de test"],"answer":0,"explanation":"Khorikov évalue un test selon quatre attributs : la protection contre les régressions (attrape-t-il les vrais bugs ?), la résistance au refactoring (survit-il aux changements internes sans faux positifs ?), la rapidité du feedback, et la maintenabilité. Les deux premiers sont en tension : maximiser la résistance au refactoring pousse à tester le comportement observable plutôt que l'implémentation.","tags":["khorikov","quatre-piliers","resistance-refactoring","regression"],"optionNotes":["Protection contre les régressions, résistance au refactoring, feedback rapide, maintenabilité.","Maximiser la couverture ou minimiser les lignes ne fait pas partie des piliers de Khorikov.","Lisibilité et exécution parallèle sont utiles mais ne sont pas les quatre piliers cités.","Portabilité et sécurité des données ne figurent pas parmi les quatre attributs de Khorikov."]},
  {"id":"tst-rendre-testable-un-code-dependant-du-tem","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"Rendre testable un code dépendant du temps","company":"Vladimir Khorikov, «Unit Testing...», ch. 6 (dépendances)","question":"Comment rendre déterministe un code dont le comportement dépend de l'heure courante ?","options":["Injecter une abstraction d'horloge que le test contrôle, au lieu d'appeler l'horloge système","Ajouter une pause temporisée dans le test afin de synchroniser les horloges des machines","Réexécuter le test plusieurs fois et conserver le résultat majoritaire parmi les exécutions","Comparer l'heure obtenue avec une tolérance aléatoire recalculée à chaque exécution du test"],"answer":0,"explanation":"Un appel direct à l'horloge système (now()) rend le résultat non déterministe. On extrait cette dépendance derrière une abstraction (une interface Clock, ou une fonction injectée) que le code de production reçoit. En test, on fournit une horloge figée à une valeur choisie ; en production, l'horloge réelle. Le comportement devient reproductible et vérifiable exactement.","tags":["temps","horloge","injection","determinisme"],"optionNotes":["On injecte une abstraction d'horloge que le test fige, au lieu d'appeler l'horloge système.","Une pause temporisée ne fixe pas le temps : elle ralentit le test et reste non déterministe.","Garder un résultat majoritaire masque le problème au lieu de rendre le code déterministe.","Une tolérance aléatoire réintroduit du hasard : il faut contrôler le temps, pas l'approximer."]},
  {"id":"tst-le-shrinking-en-property-based-testing","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"Le shrinking en property-based testing","company":"Claessen & Hughes, QuickCheck","question":"À quoi sert le « shrinking » en property-based testing ?","options":["Réduire un contre-exemple trouvé à sa forme minimale pour faciliter le diagnostic du bug","Diminuer le nombre total de propriétés testées afin d'accélérer l'exécution de la suite","Compresser en mémoire les jeux de données générés pour économiser des ressources machine","Supprimer les entrées valides pour ne conserver au final que les cas d'erreur détectés"],"answer":0,"explanation":"Quand un framework de property-based testing trouve une entrée qui viole une propriété, cette entrée est souvent grosse et bruitée. Le shrinking la réduit automatiquement à un contre-exemple minimal (la plus petite liste, le plus petit nombre) qui reproduit encore l'échec. Cela transforme un cas illisible en un exemple minimal, bien plus facile à comprendre et à corriger.","tags":["property-based","shrinking","contre-exemple","quickcheck"],"optionNotes":["Le shrinking réduit un contre-exemple trouvé à sa forme minimale pour faciliter le diagnostic.","Il ne touche pas au nombre de propriétés : il minimise un cas d'échec, pas la suite.","Il ne compresse pas la mémoire : il simplifie logiquement l'entrée qui viole la propriété.","Il ne supprime pas les entrées valides : il rétrécit l'unique contre-exemple fautif."]},
  {"id":"tst-le-contract-testing-pilote-par-le-consom","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"Le contract testing piloté par le consommateur","company":"Pact, «Consumer-Driven Contracts»; Martin Fowler","question":"Que signifie un contract testing « consumer-driven » (piloté par le consommateur) ?","options":["Les attentes du consommateur définissent le contrat que le producteur doit ensuite vérifier","Le producteur impose son schéma et le consommateur doit s'y conformer sans aucun test propre","Chaque consommateur exécute intégralement la suite de tests end-to-end du service producteur","Le contrat est régénéré aléatoirement à chaque déploiement du service producteur en recette"],"answer":0,"explanation":"Dans l'approche consumer-driven (ex. Pact), chaque consommateur exprime, sous forme de contrat, exactement ce dont il a besoin de l'API. Ces contrats sont ensuite rejoués côté producteur pour vérifier qu'il continue de les honorer. L'API sait ainsi précisément ce que ses clients utilisent et peut évoluer sans casser des champs pourtant consommés — sans recourir à un lourd test e2e commun.","tags":["contract-testing","consumer-driven","pact","compatibilite"],"optionNotes":["Les attentes du consommateur définissent le contrat, que le producteur rejoue pour le vérifier.","À l'inverse du consumer-driven, ici le producteur n'impose pas son schéma sans test client.","Le consommateur ne rejoue pas la suite e2e du producteur : il exprime juste ses besoins.","Le contrat est stable et versionné, pas régénéré aléatoirement à chaque déploiement."]},
  {"id":"tst-des-tests-qui-cassent-a-chaque-refactori","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"Des tests qui cassent à chaque refactoring","company":"Vladimir Khorikov, «Unit Testing...», ch. 5; Freeman & Pryce","scenario":"Vos tests cassent à chaque refactoring interne, alors que le comportement observable du système reste rigoureusement inchangé.","question":"Quel est le remède le plus approprié ?","options":["Tester via l'API publique observable plutôt que les détails d'implémentation de l'objet","Augmenter le nombre de mocks afin d'isoler encore davantage chaque classe interne du module","Supprimer les assertions devenues gênantes et se fier uniquement au taux de couverture de code","Fusionner l'ensemble des tests en un seul gros test afin de réduire le coût de maintenance"],"answer":0,"explanation":"Des tests qui cassent sans régression réelle sont fragiles : ils sont couplés à l'implémentation (états privés, ordre d'appels internes, collaborateurs mockés). Le remède est de tester le comportement observable via l'API publique, de sorte qu'un refactoring interne les laisse verts. Ajouter des mocks aggraverait le couplage ; supprimer les assertions détruirait la protection contre les régressions.","tags":["fragilite","refactoring","api-publique","comportement"],"optionNotes":["Tester l'API publique observable laisse les tests verts après un refactoring interne.","Ajouter des mocks aggrave le couplage à l'implémentation, donc la fragilité.","Supprimer les assertions détruirait la protection contre les régressions : mauvaise idée.","Fusionner tout en un seul test nuit à la lisibilité sans régler le couplage."]},
  {"id":"tst-preferer-un-fake-a-un-mock-pour-une-base","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"Préférer un fake à un mock pour une base","company":"Gerard Meszaros; Vladimir Khorikov, «Unit Testing...», ch. 8","question":"Pourquoi préférer un « fake » (base en mémoire) à un mock pour la base de données dans certains tests ?","options":["Le fake reproduit le comportement réel sans figer les interactions, ce qui réduit la fragilité","Le fake est nécessairement toujours plus rapide car il n'exécute aucune logique métier interne","Le fake garantit d'atteindre exactement cent pour cent de couverture sur la couche d'accès aux données","Le fake vérifie automatiquement l'ordre exact des requêtes SQL émises par le code de production"],"answer":0,"explanation":"Un fake (par exemple un dépôt en mémoire respectant le même contrat) laisse le code interagir avec une implémentation réaliste et vérifie le résultat par l'état. Contrairement à un mock qui fige la séquence exacte des appels, il ne casse pas quand on réorganise ces appels sans changer le comportement. Pour les dépendances qu'on contrôle entièrement, un fake donne des tests plus robustes et lisibles.","tags":["fake","mock","base-de-donnees","robustesse"],"optionNotes":["Le fake reproduit le comportement réel sans figer les appels : moins fragile qu'un mock.","Faux : un fake exécute une vraie logique allégée ; il n'est pas forcément plus rapide.","Un fake ne garantit aucune couverture de 100 % sur la couche d'accès aux données.","Vérifier l'ordre exact des requêtes SQL est le fait d'un mock, pas d'un fake."]},
  {"id":"tst-ecouter-ce-que-disent-les-tests","type":"mcq","domain":"software","topic":"testing","difficulty":"senior","title":"Écouter ce que disent les tests","company":"Freeman & Pryce, «Growing Object-Oriented Software, Guided by Tests», «Listen to the tests»","question":"Selon « Growing Object-Oriented Software », que révèle souvent un test difficile à écrire ?","options":["Un problème de conception (couplage fort, responsabilités mal réparties) qu'il faut corriger","Un manque de puissance de la machine exécutant la suite de tests du projet concerné","La nécessité d'écrire d'abord le code de production, puis seulement ensuite les tests associés","Un framework de test inadapté qu'il faut immédiatement remplacer par un outil plus récent"],"answer":0,"explanation":"Freeman et Pryce insistent : la difficulté à écrire un test est un signal de conception (« listen to the tests »). Un objet pénible à instancier, à isoler ou dont il faut mocker une nuée de dépendances trahit un couplage excessif ou des responsabilités mal découpées. En TDD guidé par les tests, cette friction pousse à améliorer le design plutôt qu'à contourner le test.","tags":["goos","conception","couplage","design-feedback"],"optionNotes":["Un test pénible à écrire signale souvent un défaut de conception : couplage fort, responsabilités floues.","La difficulté ne vient pas de la machine : c'est un signal de design, pas de performance.","« Listen to the tests » guide le design en TDD ; il ne prône pas d'écrire le code d'abord.","Le framework n'est pas en cause : la friction révèle un problème de conception à corriger."]},
  {"id":"tst-le-test-de-token-intermittent","type":"find-error","domain":"software","topic":"testing","difficulty":"senior","title":"Le test de token intermittent","company":"Martin Fowler, «Eradicating Non-Determinism in Tests»","language":"python","code":"from datetime import datetime, timedelta\n\ndef test_token_expire_dans_une_heure():\n    token = creer_token()\n    attendu = datetime.now() + timedelta(hours=1)\n    assert token.expires_at == attendu","question":"Pourquoi ce test est-il flaky (parfois vert, parfois rouge) ?","options":["datetime.now() du test diffère de l'instant de création du token : l'égalité stricte échoue par intermittence","timedelta(hours=1) est incompatible avec un objet datetime et provoque une erreur de type","expires_at devrait être comparé avec l'opérateur >=, mais le test échouerait alors toujours","creer_token() doit être remplacé par un mock, sans quoi le test ne peut jamais être exécuté"],"answer":0,"explanation":"creer_token() capture l'heure au moment de la création ; le test rappelle datetime.now() quelques microsecondes plus tard. Les deux instants diffèrent, donc l'égalité stricte échoue de façon intermittente selon le timing d'exécution. La solution est de contrôler le temps : injecter une horloge figée dans creer_token(), ou comparer avec une tolérance (assert abs(token.expires_at - attendu) < timedelta(seconds=1)).","tags":["flaky","temps","horloge","determinisme"],"optionNotes":["Le now() du test diffère de l'instant de création du token : l'égalité stricte échoue par moments.","Faux : timedelta s'additionne parfaitement à un datetime, sans erreur de type.","Passer à >= ne suffit pas ici et le test échouerait toujours : il faut contrôler le temps.","Mocker creer_token n'est pas requis : il faut figer l'horloge ou comparer avec tolérance."]},
  {"id":"tst-le-test-qui-ne-verifie-que-le-mock","type":"find-error","domain":"software","topic":"testing","difficulty":"senior","title":"Le test qui ne vérifie que le mock","company":"Vladimir Khorikov, «Unit Testing...», ch. 5; Gerard Meszaros (Test Smell)","language":"javascript","code":"test('envoie un email de bienvenue', () => {\n  const mailer = { envoyer: jest.fn() };\n  mailer.envoyer('bienvenue');\n  expect(mailer.envoyer).toHaveBeenCalledWith('bienvenue');\n});","question":"Quel est le problème fondamental de ce test ?","options":["Il vérifie le mock lui-même et non le code de production : il est tautologique et ne prouve rien","jest.fn() est incapable d'enregistrer les arguments d'un appel dans l'environnement JavaScript","toHaveBeenCalledWith exige impérativement un second argument qui est manquant dans cet appel","Le mailer aurait dû être un stub renvoyant une valeur plutôt qu'un mock enregistrant l'appel"],"answer":0,"explanation":"Le test appelle directement mailer.envoyer(...) puis vérifie que mailer.envoyer a été appelé : il teste le mock qu'il vient d'écrire, pas le système sous test. Aucun code de production n'est exercé, donc rien de réel n'est validé — c'est un test tautologique. Il faudrait instancier le vrai composant (ex. un WelcomeService(mailer)), appeler sa méthode métier, puis vérifier qu'il a bien sollicité le mailer.","tags":["tautologique","mock","test-smell","sut"],"optionNotes":["Le test appelle puis vérifie le mock lui-même : tautologique, il n'exerce aucun code de production.","Faux : jest.fn() enregistre bien les arguments d'appel ; le souci est l'absence de SUT.","toHaveBeenCalledWith accepte un seul argument : ce n'est pas la cause du problème.","Un stub ne réglerait rien : il manque surtout un vrai composant à tester."]},
  {"id":"tst-deux-tests-qui-se-contaminent","type":"find-error","domain":"software","topic":"testing","difficulty":"senior","title":"Deux tests qui se contaminent","company":"Roy Osherove, «The Art of Unit Testing», ch. 7 (FIRST)","language":"python","code":"comptes = {}\n\ndef test_credit():\n    comptes['a'] = 100\n    assert solde('a') == 100\n\ndef test_solde_initial_vide():\n    assert 'a' not in comptes","question":"Quel principe FIRST est violé par ces deux tests ?","options":["L'isolation : test_solde_initial_vide dépend de l'ordre d'exécution via l'état global partagé comptes","La rapidité : l'accès au dictionnaire comptes ralentit de façon exagérée l'ensemble de la suite","L'auto-vérification : les deux tests manquent en réalité d'une assertion finale explicite du résultat","La répétabilité : la fonction solde('a') renvoie une valeur aléatoire différente à chaque appel"],"answer":0,"explanation":"Les deux tests partagent la variable globale comptes. test_credit() y écrit 'a', si bien que test_solde_initial_vide passe seulement s'il s'exécute avant : le verdict dépend de l'ordre. C'est une violation de l'isolation/indépendance (le I de FIRST) et une source classique de flaky en exécution parallèle ou réordonnée. Il faut un état propre par test (fixture réinitialisée, données locales) plutôt qu'un dictionnaire global partagé.","tags":["isolation","etat-partage","first","test-pollution"],"optionNotes":["Le dictionnaire global comptes lie les deux tests : le verdict dépend de l'ordre d'exécution.","La rapidité n'est pas en cause : un accès à un dict est instantané, pas un ralentisseur.","Les deux tests ont bien une assertion : le défaut est l'isolation, pas l'auto-vérification.","solde('a') n'est pas aléatoire : c'est l'état global partagé qui casse l'indépendance."]},
];
